head.b:skin:
/* Typzen - Blogger theme. Page-level resets for the Blogger body. */
html,body{margin:0;padding:0;height:100%;overflow:hidden;background:#f6f0e3}
#navbar,#navbar-iframe,.navbar{display:none!important;height:0!important}
/* ---------- Theme tokens (everything is scoped to #typzen-app) ---------- */
#typzen-app{
  --bg:#f6f0e3; --surface:#fffaf1; --ink:#2f2d2b; --soft:#7a746a;
  --pending:rgba(47,45,43,.28); --chip:rgba(80,60,30,.07);
  --accent:#86a38e; --accent-d:#5d8068; --accent2:#9c8fd1; --accent2-d:#7b6cc0;
  --bad:#c2405c; --bad-bg:rgba(233,110,135,.22);
  --shadow:0 12px 32px rgba(90,70,40,.09),0 2px 6px rgba(90,70,40,.05);
  --glow1:rgba(156,143,209,.16); --glow2:rgba(134,163,142,.18); --ring:rgba(156,143,209,.55);
  --mono:"JetBrains Mono","Fira Code","SF Mono",ui-monospace,Menlo,Consolas,"Liberation Mono","Courier New",monospace;
  --sans:ui-rounded,"SF Pro Rounded","Segoe UI",system-ui,-apple-system,Roboto,"Helvetica Neue",Arial,sans-serif;
  --serif:Georgia,"Times New Roman",serif;
}
#typzen-app[data-theme="dark"]{
  --bg:#1e1c22; --surface:#2a272f; --ink:#ece6d9; --soft:#a49d92;
  --pending:rgba(236,230,217,.27); --chip:rgba(255,255,255,.07);
  --accent:#8fb39a; --accent-d:#a9cdb3; --accent2:#b5a8ec; --accent2-d:#c3b8f2;
  --bad:#ff8aa0; --bad-bg:rgba(255,120,150,.2);
  --shadow:0 12px 34px rgba(0,0,0,.35),0 2px 6px rgba(0,0,0,.2);
  --glow1:rgba(181,168,236,.10); --glow2:rgba(143,179,154,.08); --ring:rgba(181,168,236,.55);
}

/* ---------- Isolation from Blogger template styles ---------- */
#typzen-app,#typzen-app *,#typzen-app *::before,#typzen-app *::after{
  box-sizing:border-box;margin:0;padding:0;border:0;background:none;font:inherit;color:inherit;
  text-decoration:none;text-shadow:none;letter-spacing:normal;text-transform:none;float:none;
  list-style:none;-webkit-tap-highlight-color:transparent;
}
#typzen-app{
  position:fixed;top:0;right:0;bottom:0;left:0;z-index:2147483000;
  overflow-x:hidden;overflow-y:auto;-webkit-overflow-scrolling:touch;
  background:radial-gradient(1100px 560px at 12% -8%,var(--glow1),transparent 60%),
             radial-gradient(900px 520px at 100% 8%,var(--glow2),transparent 55%),var(--bg);
  color:var(--ink);font-family:var(--sans);font-size:16px;line-height:1.5;
  -webkit-font-smoothing:antialiased;-webkit-text-size-adjust:100%;text-align:left;
}
#typzen-app.tp-inline{position:relative;z-index:auto;top:auto;right:auto;bottom:auto;left:auto;border-radius:20px}
#typzen-app button{cursor:pointer;-webkit-appearance:none;appearance:none;outline:none;user-select:none;-webkit-user-select:none}
#typzen-app button:focus-visible{box-shadow:0 0 0 3px var(--ring)}
#typzen-app svg{display:block}

/* ---------- Layout ---------- */
#typzen-app .tp-wrap{width:100%;max-width:900px;margin:0 auto;padding:18px 20px 34px;min-height:100%;display:flex;flex-direction:column}
#typzen-app.tp-inline .tp-wrap{min-height:90vh}
#typzen-app .tp-head{display:flex;align-items:center;justify-content:space-between;padding:4px 2px 0}
#typzen-app .tp-logo{display:flex;align-items:center;gap:10px;font-family:var(--serif);font-size:1.65rem;font-weight:600;letter-spacing:-.01em}
#typzen-app .tp-logo svg{width:30px;height:30px}
#typzen-app .tp-nav{display:flex;align-items:center;gap:6px}
#typzen-app .tp-link{padding:8px 14px;border-radius:999px;color:var(--soft);font-size:.95rem;transition:background .2s,color .2s}
#typzen-app .tp-link:hover{background:var(--chip);color:var(--ink)}
#typzen-app .tp-iconbtn{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;color:var(--soft);transition:background .2s,color .2s,transform .3s}
#typzen-app .tp-iconbtn:hover{background:var(--chip);color:var(--ink)}
#typzen-app .tp-iconbtn:active{transform:scale(.92)}
#typzen-app .tp-iconbtn svg{width:20px;height:20px}
#typzen-app .tp-ico-sun{display:none}
#typzen-app[data-theme="dark"] .tp-ico-sun{display:block}
#typzen-app[data-theme="dark"] .tp-ico-moon{display:none}
#typzen-app .tp-ico-sndon{display:none}
#typzen-app[data-sound="on"] .tp-ico-sndon{display:block}
#typzen-app[data-sound="on"] .tp-ico-sndoff{display:none}
#typzen-app #tp-sound[aria-pressed="true"]{color:var(--accent-d)}

#typzen-app .tp-main{flex:1;display:flex;flex-direction:column;justify-content:center;padding:14px 0 10px}
#typzen-app .tp-main[data-view="test"] .tp-result{display:none}
#typzen-app .tp-main[data-view="result"] .tp-test{display:none}

#typzen-app .tp-tag{text-align:center;color:var(--soft);font-family:var(--serif);font-style:italic;font-size:1.05rem;transition:opacity .5s}

/* ---------- Stats ---------- */
#typzen-app .tp-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:16px 0 14px}
#typzen-app .tp-stat{background:var(--surface);border-radius:18px;padding:13px 10px;box-shadow:var(--shadow);text-align:center}
#typzen-app .tp-stat b{display:block;font-size:clamp(1.5rem,5vw,2.15rem);font-weight:600;font-variant-numeric:tabular-nums;line-height:1.15}
#typzen-app .tp-stat span{display:block;font-size:.7rem;letter-spacing:.14em;text-transform:uppercase;color:var(--soft);margin-top:2px}
#typzen-app #tp-wpm{color:var(--accent-d)}
#typzen-app #tp-time{color:var(--accent2-d)}

/* ---------- Controls ---------- */
#typzen-app .tp-bar{display:flex;align-items:center;justify-content:space-between;gap:10px 14px;flex-wrap:wrap;margin-bottom:12px;transition:opacity .5s}
#typzen-app .tp-seg{display:inline-flex;gap:2px;padding:4px;border-radius:999px;background:var(--chip)}
#typzen-app .tp-seg button{padding:7px 16px;border-radius:999px;font-size:.9rem;color:var(--soft);transition:background .2s,color .2s,box-shadow .2s}
#typzen-app .tp-seg button:hover{color:var(--ink)}
#typzen-app .tp-seg button[aria-pressed="true"]{background:var(--surface);color:var(--ink);box-shadow:0 2px 8px rgba(0,0,0,.08)}
#typzen-app .tp-pb{font-size:.85rem;color:var(--soft)}
#typzen-app .tp-pb b{color:var(--accent-d);font-weight:600}

/* ---------- Typing card (the heart) ---------- */
#typzen-app .tp-card{position:relative;background:var(--surface);border-radius:26px;padding:24px clamp(18px,4vw,40px);box-shadow:var(--shadow);cursor:text;overflow:hidden}
#typzen-app .tp-view{position:relative;overflow:hidden;height:calc(1.95em*3);
  -webkit-mask-image:linear-gradient(180deg,rgba(0,0,0,.2) 0%,rgba(0,0,0,.5) 28%,#000 40%,#000 62%,rgba(0,0,0,.4) 74%,rgba(0,0,0,.08) 100%);
          mask-image:linear-gradient(180deg,rgba(0,0,0,.2) 0%,rgba(0,0,0,.5) 28%,#000 40%,#000 62%,rgba(0,0,0,.4) 74%,rgba(0,0,0,.08) 100%)}
#typzen-app .tp-text{position:relative;font-family:var(--mono);font-size:clamp(1.05rem,.8rem + 1.3vw,1.6rem);line-height:1.95;
  color:var(--pending);padding-top:3.7rem;transition:transform .32s cubic-bezier(.4,.1,.2,1),filter .3s,opacity .3s;will-change:transform;text-align:left}
#typzen-app .tp-word{display:inline-block;white-space:pre;vertical-align:top}
#typzen-app .tp-ch{position:relative;border-radius:4px;transition:color .12s,background-color .12s}
#typzen-app .tp-ch.ok{color:var(--ink)}
#typzen-app .tp-ch.bad{color:var(--bad);background:var(--bad-bg)}
#typzen-app .tp-ch.cur::before{content:"";position:absolute;left:-1px;top:.14em;bottom:.14em;width:2px;border-radius:2px;background:var(--accent2);animation:tp-blink 1.1s ease-in-out infinite}
@keyframes tp-blink{0%,45%{opacity:1}60%,100%{opacity:.1}}
#typzen-app .tp-input{position:absolute;left:0;top:0;width:1px;height:1px;opacity:0;padding:0;border:0;font-size:16px;pointer-events:none;caret-color:transparent;background:transparent}
#typzen-app .tp-focusmsg{position:absolute;top:0;right:0;bottom:0;left:0;display:none;align-items:center;justify-content:center;
  font-size:.95rem;color:var(--ink);background:rgba(128,128,128,.08);-webkit-backdrop-filter:blur(3px);backdrop-filter:blur(3px)}
#typzen-app .tp-card.tp-blur .tp-focusmsg{display:flex}
#typzen-app .tp-card.tp-blur .tp-text{opacity:.6}

#typzen-app .tp-hint{text-align:center;margin-top:16px;color:var(--soft);font-size:.95rem;transition:opacity .5s;animation:tp-pulse 2.4s ease-in-out infinite}
@keyframes tp-pulse{0%,100%{opacity:.55}50%{opacity:1}}
#typzen-app .tp-actions{display:flex;justify-content:center;margin-top:10px;transition:opacity .5s}
#typzen-app .tp-ghost{display:inline-flex;align-items:center;gap:8px;padding:10px 18px;border-radius:999px;background:var(--chip);color:var(--soft);font-size:.92rem;transition:color .2s,transform .2s}
#typzen-app .tp-ghost:hover{color:var(--ink)}
#typzen-app .tp-ghost:active{transform:scale(.96)}
#typzen-app .tp-ghost svg{width:16px;height:16px}

/* Calm focus mode while typing */
#typzen-app.tp-running .tp-bar,#typzen-app.tp-running .tp-tag,#typzen-app.tp-running .tp-actions{opacity:.3}
#typzen-app.tp-running .tp-hint{opacity:0;animation:none}

/* ---------- Result ---------- */
#typzen-app .tp-result{display:block;width:100%;max-width:640px;margin:0 auto}
#typzen-app .tp-rcard{background:var(--surface);border-radius:30px;box-shadow:var(--shadow);padding:30px clamp(18px,5vw,40px) 32px;text-align:center;animation:tp-rise .6s cubic-bezier(.2,.8,.2,1) both}
@keyframes tp-rise{from{opacity:0;transform:translateY(14px) scale(.98)}to{opacity:1;transform:none}}
#typzen-app .tp-check{position:relative;width:72px;height:72px;margin:0 auto 8px}
#typzen-app .tp-check svg{width:72px;height:72px;overflow:visible}
#typzen-app .tp-ring{fill:none;stroke:var(--accent);stroke-width:4;stroke-linecap:round;stroke-dasharray:176;stroke-dashoffset:176;transform:rotate(-90deg);transform-origin:50% 50%;animation:tp-draw .8s .1s ease forwards}
#typzen-app .tp-tick{fill:none;stroke:var(--accent-d);stroke-width:4.5;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:40;stroke-dashoffset:40;animation:tp-draw .5s .75s ease forwards}
@keyframes tp-draw{to{stroke-dashoffset:0}}
#typzen-app .tp-sparks{position:absolute;left:50%;top:50%;width:0;height:0}
#typzen-app .tp-spark{position:absolute;left:-4px;top:-4px;width:8px;height:8px;border-radius:50%;opacity:0;animation:tp-spark 1.4s ease-out forwards}
@keyframes tp-spark{0%{opacity:0;transform:translate(0,0) scale(.3)}25%{opacity:1}100%{opacity:0;transform:translate(var(--dx),var(--dy)) scale(1)}}
#typzen-app .tp-rtitle{font-family:var(--serif);font-size:1.7rem;font-weight:600;margin-top:4px}
#typzen-app .tp-badge{display:none;margin:10px auto 0;padding:5px 14px;border-radius:999px;font-size:.85rem;font-weight:600;color:var(--accent-d);background:var(--chip);animation:tp-pop .6s .9s cubic-bezier(.3,1.6,.5,1) both}
#typzen-app .tp-badge.tp-on{display:inline-block}
@keyframes tp-pop{from{opacity:0;transform:scale(.6)}to{opacity:1;transform:none}}
#typzen-app .tp-hero{display:flex;justify-content:center;gap:clamp(24px,8vw,64px);margin:22px 0 18px}
#typzen-app .tp-hero b{display:block;font-size:clamp(2.6rem,10vw,3.8rem);font-weight:600;line-height:1;font-variant-numeric:tabular-nums}
#typzen-app .tp-hero div:first-child b{color:var(--accent-d)}
#typzen-app .tp-hero span{display:block;margin-top:6px;font-size:.72rem;letter-spacing:.14em;text-transform:uppercase;color:var(--soft)}
#typzen-app .tp-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:18px}
#typzen-app .tp-grid div{background:var(--chip);border-radius:16px;padding:12px 6px}
#typzen-app .tp-grid b{display:block;font-size:1.25rem;font-weight:600;font-variant-numeric:tabular-nums}
#typzen-app .tp-grid span{display:block;font-size:.66rem;letter-spacing:.1em;text-transform:uppercase;color:var(--soft);margin-top:2px}
#typzen-app .tp-pbline{font-size:.88rem;color:var(--soft);margin-bottom:6px}
#typzen-app .tp-pbline b{color:var(--accent-d);font-weight:600}
#typzen-app .tp-insight{font-size:1rem;color:var(--ink);margin:6px auto 24px;max-width:46ch}
#typzen-app .tp-btns{display:flex;justify-content:center;gap:12px;flex-wrap:wrap}
#typzen-app .tp-primary{padding:13px 30px;border-radius:999px;background:var(--accent-d);color:#fff;font-weight:600;font-size:1rem;box-shadow:0 8px 20px rgba(93,128,104,.3);transition:transform .2s,box-shadow .2s,filter .2s}
#typzen-app[data-theme="dark"] .tp-primary{color:#1b1a1f;background:var(--accent-d)}
#typzen-app .tp-primary:hover{transform:translateY(-2px);filter:brightness(1.05)}
#typzen-app .tp-primary:active{transform:scale(.97)}
#typzen-app .tp-secondary{padding:13px 26px;border-radius:999px;background:var(--chip);color:var(--ink);font-size:1rem;transition:transform .2s,background .2s}
#typzen-app .tp-secondary:hover{transform:translateY(-2px)}
#typzen-app .tp-secondary:active{transform:scale(.97)}

/* ---------- About modal ---------- */
#typzen-app .tp-modal{position:fixed;top:0;right:0;bottom:0;left:0;z-index:5;display:none;align-items:center;justify-content:center;padding:20px;background:rgba(30,25,35,.38);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}
#typzen-app .tp-modal.tp-open{display:flex;animation:tp-fade .25s ease both}
@keyframes tp-fade{from{opacity:0}to{opacity:1}}
#typzen-app .tp-about{position:relative;width:100%;max-width:460px;background:var(--surface);border-radius:28px;box-shadow:var(--shadow);padding:34px 30px 30px;text-align:center;animation:tp-rise .4s cubic-bezier(.2,.8,.2,1) both}
#typzen-app .tp-about h2{font-family:var(--serif);font-size:1.6rem;font-weight:600;margin-bottom:12px}
#typzen-app .tp-about p{color:var(--soft);font-size:.98rem;margin-bottom:10px}
#typzen-app .tp-divider{width:44px;height:3px;border-radius:3px;margin:18px auto;background:linear-gradient(90deg,var(--accent),var(--accent2))}
#typzen-app .tp-by{font-size:.72rem;letter-spacing:.14em;text-transform:uppercase;color:var(--soft)}
#typzen-app .tp-name{font-family:var(--serif);font-size:1.3rem;font-weight:600;margin-top:6px}
#typzen-app .tp-role{font-size:.9rem;color:var(--accent2-d);margin-top:2px}
#typzen-app .tp-x{position:absolute;top:12px;right:12px}

/* ---------- Small screens ---------- */
@media (max-width:520px){
  #typzen-app .tp-wrap{padding:12px 14px 24px}
  #typzen-app .tp-stats{gap:8px}
  #typzen-app .tp-card{padding:18px 16px;border-radius:22px}
  #typzen-app .tp-grid{grid-template-columns:repeat(2,1fr)}
  #typzen-app .tp-logo{font-size:1.45rem}
}
@media (max-height:560px){ #typzen-app .tp-tag{display:none} #typzen-app .tp-stats{margin:10px 0} }
@media (prefers-reduced-motion:reduce){
  #typzen-app *,#typzen-app *::before,#typzen-app *::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}
}

body.script:
//
(function () {
  'use strict';

  /* ===== Settings ===== */
  var FULLSCREEN = true;           // true: Typzen covers the whole Blogger page. false: sits inside the page content.
  var DURATIONS = [15, 30, 60];
  var TARGET_LEN = { 15: 260, 30: 480, 60: 900 };   // starting passage length (characters); more is appended on demand

  /* ===== Passages (original, simple everyday English) ===== */
  var PASSAGES = [
    "The morning sun spilled over the hills, and the whole town woke up slowly with a warm cup of tea.",
    "A small cat sat by the window and watched the rain draw tiny rivers down the glass.",
    "She packed a book, a blanket and some fruit, then walked to the quiet spot by the lake.",
    "Good habits are built one small step at a time, so be kind to yourself and keep going.",
    "We cooked a simple soup, shared fresh bread, and talked until the candles burned low.",
    "The bus was late again, but the song in my headphones made the wait feel short.",
    "Every evening, my grandfather waters his plants and tells them stories about the old days.",
    "A clear mind and a steady rhythm will take you further than rushing ever could.",
    "The market was full of color, with bright oranges, green herbs and baskets of sweet bread.",
    "He found a small shell on the beach and kept it in his pocket for good luck.",
    "Learning something new can feel slow at first, but each day it gets a little easier.",
    "The library was calm and quiet, and the only sound was the soft turning of pages.",
    "Rain tapped on the roof while we played cards, laughed at silly jokes and ate warm cookies.",
    "Take a deep breath, relax your shoulders, and let your fingers find their own gentle pace.",
    "On Sunday we rode our bikes along the river and stopped to feed the ducks near the bridge.",
    "A tidy desk, a cup of coffee and a little music can make any task feel lighter.",
    "The stars came out one by one, and the night felt wide, calm and full of wonder.",
    "My friend baked a lemon cake for my birthday, and we ate it on the balcony at sunset.",
    "Practice does not need to be perfect. It only needs to be regular and kind.",
    "The old train rolled through green fields while we watched the clouds change shape.",
    "Fresh snow covered the street, and the children ran outside with scarves and big smiles.",
    "I like to start my day with a short walk, a glass of water and a few quiet minutes.",
    "A good story can take you to faraway places without ever leaving your favorite chair.",
    "The baker opened his shop before dawn, and soon the whole street smelled like warm butter.",
    "Small wins matter. Each word you type brings you closer to faster and calmer fingers.",
    "We planted tomatoes in spring, and by summer the garden was full of red and green.",
    "When the day feels heavy, put on soft music, sit by the window and take it slow.",
    "The little boat drifted across the pond as the wind hummed a slow and gentle tune.",
    "She wrote her goals in a notebook and checked them off one by one with a happy smile.",
    "Our dog loves the park, especially when the leaves are crunchy and the air is cool.",
    "Slow and steady wins the race, so keep your eyes on the words and enjoy the ride.",
    "Light from the lamp made the room feel warm, and the cat curled up beside the books."
  ];

  var host = document.getElementById('typzen-app');
  if (!host) { return; }

  /* ===== Storage (LocalStorage only for best score + preferences) ===== */
  function load(k, d) { try { var v = window.localStorage.getItem(k); return v === null ? d : v; } catch (e) { return d; } }
  function save(k, v) { try { window.localStorage.setItem(k, String(v)); } catch (e) {} }

  /* ===== Markup ===== */
  host.innerHTML =
    '<div class="tp-wrap">' +
      '<header class="tp-head">' +
        '<div class="tp-logo">' +
          '<svg viewBox="0 0 32 32" aria-hidden="true"><rect x="2" y="3" width="28" height="26" rx="9" style="fill:var(--accent)"/><path d="M10.5 11.5h11M16 11.5v10" stroke="#fff" stroke-width="2.8" stroke-linecap="round" fill="none"/><circle cx="24" cy="22.5" r="1.7" fill="#fff" opacity=".8"/></svg>' +
          '<span>Typzen</span>' +
        '</div>' +
        '<nav class="tp-nav">' +
          '<button type="button" class="tp-link" id="tp-about-btn">About</button>' +
          '<button type="button" class="tp-iconbtn" id="tp-sound" aria-label="Sound effects off" aria-pressed="false" title="Sound effects: off">' +
            '<svg class="tp-ico-sndoff" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 5L6 9H2v6h4l5 4z"/><path d="M22 9l-6 6M16 9l6 6"/></svg>' +
            '<svg class="tp-ico-sndon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 5L6 9H2v6h4l5 4z"/><path d="M15.5 8.5a5 5 0 0 1 0 7M18.5 5.5a9 9 0 0 1 0 13"/></svg>' +
          '</button>' +
          '<button type="button" class="tp-iconbtn" id="tp-theme" aria-label="Switch between light and dark theme" title="Light / Dark">' +
            '<svg class="tp-ico-moon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 13.5A8.5 8.5 0 1 1 10.5 3a7 7 0 0 0 10.5 10.5z"/></svg>' +
            '<svg class="tp-ico-sun" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg>' +
          '</button>' +
        '</nav>' +
      '</header>' +

      '<main class="tp-main" id="tp-main" data-view="test">' +
        '<section class="tp-test">' +
          '<p class="tp-tag">A little space to type, focus &amp; grow.</p>' +
          '<div class="tp-stats">' +
            '<div class="tp-stat"><b id="tp-wpm">0</b><span>WPM</span></div>' +
            '<div class="tp-stat"><b id="tp-acc">100%</b><span>Accuracy</span></div>' +
            '<div class="tp-stat"><b id="tp-time">30</b><span>Seconds</span></div>' +
          '</div>' +
          '<div class="tp-bar">' +
            '<div class="tp-seg" role="group" aria-label="Test duration" id="tp-seg">' +
              '<button type="button" data-d="15" aria-pressed="false">15s</button>' +
              '<button type="button" data-d="30" aria-pressed="true">30s</button>' +
              '<button type="button" data-d="60" aria-pressed="false">60s</button>' +
            '</div>' +
            '<div class="tp-pb" id="tp-pb"></div>' +
          '</div>' +
          '<div class="tp-card tp-blur" id="tp-card">' +
